("mod_redefine_keys", prsntf_manual_end_only, mesh_load_window, [
    (ti_on_presentation_load,
      [
        (presentation_set_duration, 999999),
        (set_fixed_point_multiplier, 1000),

        (call_script, "script_init_keys_array"),

        (try_for_range, ":strings", s1, s6),
          (str_clear, ":strings"),
        (try_end),
        (try_for_range, ":cur_slot", 0, len(keys)),
          (troop_get_slot, ":key_no", "trp_temp_array_a", ":cur_slot"),
          (store_add, ":dest_string", "str_key_0", ":cur_slot"),
          (try_begin),
            # # (eq, ":key_no", "$key_shieldbash"),
            # # (str_store_string, s1, ":dest_string"),
            # (eq, ":key_no", "$key_vats"),
            # (str_store_string, s1, ":dest_string"),
          # (else_try),
            (eq, ":key_no", "$key_letmepass"),
            (str_store_string, s1, ":dest_string"),
          (else_try),
            (eq, ":key_no", "$key_scavenge"),
            (str_store_string, s2, ":dest_string"),
          (else_try),
            (eq, ":key_no", "$key_run"),
            (str_store_string, s3, ":dest_string"),
          (else_try),
            (eq, ":key_no", "$key_dodge"),
            (str_store_string, s4, ":dest_string"),
          (else_try),
            (eq, ":key_no", "$key_quickfix"),
            (str_store_string, s5, ":dest_string"),
          (else_try),
            (eq, ":key_no", "$key_crouch"),
            (str_store_string, s6, ":dest_string"),            
          (try_end),
        (try_end),
        (assign, "$temp", -1),
        (create_text_overlay, reg1, "@Bound Keys", tf_center_justify),
        (position_set_x, pos1, 500),
        (position_set_y, pos1, 650),
        (overlay_set_position, reg1, pos1),
        (position_set_x, pos1, 1500),
        (position_set_y, pos1, 1500),
        (overlay_set_size, reg1, pos1),

        ## buttons
        (create_text_overlay, reg1, "@Pass through allies", tf_center_justify),
        # (create_text_overlay, reg1, "@Assisted Targeting System", tf_center_justify),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 600),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_1", s1),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 550),
        (overlay_set_position, "$g_presentation_obj_1", pos1),

        (create_text_overlay, reg1, "@Scavenge (seems unused)", tf_center_justify),
        # (create_text_overlay, reg1, "@Pass through allies", tf_center_justify),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 400),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_2", s2),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 350),
        (overlay_set_position, "$g_presentation_obj_2", pos1),

        (create_text_overlay, reg1, "@Running", tf_center_justify),
        # (create_text_overlay, reg1, "@Scavenge", tf_center_justify),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 200),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_3", s3),
        (position_set_x, pos1, 200),
        (position_set_y, pos1, 150),
        (overlay_set_position, "$g_presentation_obj_3", pos1),

        (create_text_overlay, reg1, "@Dodge", tf_center_justify),
        # (create_text_overlay, reg1, "@Running", tf_center_justify),
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 600),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_4", s4),
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 550),
        (overlay_set_position, "$g_presentation_obj_4", pos1),

        (create_text_overlay, reg1, "@Use healing", tf_center_justify), #was Quickfix
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 400),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_5", s5),
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 350),
        (overlay_set_position, "$g_presentation_obj_5", pos1),

        (create_text_overlay, reg1, "@Crouch", tf_center_justify),
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 200),
        (overlay_set_position, reg1, pos1),
        (create_game_button_overlay, "$g_presentation_obj_6", s6),
        (position_set_x, pos1, 800),
        (position_set_y, pos1, 150),
        (overlay_set_position, "$g_presentation_obj_6", pos1),

        (create_text_overlay, "$g_presentation_obj_item_select_next", "@Press a key", tf_center_justify|tf_with_outline),
        (position_set_x, pos1, 500),
        (position_set_y, pos1, 450),
        (overlay_set_position, "$g_presentation_obj_item_select_next", pos1),
        (position_set_x, pos1, 2000),
        (position_set_y, pos1, 2000),
        (overlay_set_size, "$g_presentation_obj_item_select_next", pos1),
        (overlay_set_color, "$g_presentation_obj_item_select_next", 0xFFFFFF), #white since we have black bg
        (overlay_set_display, "$g_presentation_obj_item_select_next", 0),

        # done
        (create_game_button_overlay, "$g_close_equipment_selection", "str_done"),
        (position_set_x, pos1, Screen_Width/2),
        (position_set_y, pos1, 125),
        (overlay_set_position, "$g_close_equipment_selection", pos1),

        # reset
        (create_game_button_overlay, "$g_show_no_more_respawns_remained", "str_reset_to_default"),
        (position_set_x, pos1, Screen_Width/2),
        (position_set_y, pos1, 200),
        (overlay_set_position, "$g_show_no_more_respawns_remained", pos1),

        # # description
        # (store_sub, ":string", "$g_dplmc_cam_default", 1),
        # (val_add, ":string", "str_camera_keyboard"),
        # (create_text_overlay, reg1, ":string", tf_scrollable),
        # (position_set_x, pos1, 40),
        # (position_set_y, pos1, 60),
        # (overlay_set_position, reg1, pos1),
        # (position_set_x, pos1, 260),
        # (position_set_y, pos1, 240),
        # (overlay_set_area_size, reg1, pos1),

      ]),

    (ti_on_presentation_run,
      [

      (try_begin),
        (gt, "$temp", -1),
        (overlay_set_display, "$g_presentation_obj_item_select_next", 1),
      (else_try),
        (overlay_set_display, "$g_presentation_obj_item_select_next", 0),
      (try_end),
      (try_for_range, ":cur_slot", 0, len(keys)),
        (troop_get_slot, ":key_no", "trp_temp_array_a", ":cur_slot"),
        (key_clicked, ":key_no"),
        (gt, "$temp", -1),
        (try_begin),
          (eq, "$temp", "$g_presentation_obj_1"),
          (assign, "$key_letmepass", ":key_no"),
          # (assign, "$key_vats", ":key_no"),
        (else_try),
          (eq, "$temp", "$g_presentation_obj_2"),
          (assign, "$key_scavenge", ":key_no"),
          # (assign, "$key_letmepass", ":key_no"),
        (else_try),
          (eq, "$temp", "$g_presentation_obj_3"),
          (assign, "$key_run", ":key_no"),
          # (assign, "$key_scavenge", ":key_no"),
        (else_try),
          (eq, "$temp", "$g_presentation_obj_4"),
          (assign, "$key_dodge", ":key_no"),
        (else_try),
          (eq, "$temp", "$g_presentation_obj_5"),
          (assign, "$key_quickfix", ":key_no"),
        (else_try),
          (eq, "$temp", "$g_presentation_obj_6"),
          (assign, "$key_crouch", ":key_no"),
        (try_end),
        (store_add, ":dest_string", "str_key_0", ":cur_slot"),
        (str_store_string, s1, ":dest_string"),
        (overlay_set_text, "$temp", s1),
        (overlay_set_alpha, "$temp", 0xff),
        (assign, "$temp", -1),
      (try_end),
    ]),

    (ti_on_presentation_event_state_change,
      [
        (store_trigger_param_1, ":object"),

        (set_fixed_point_multiplier, 1000),
        (try_begin),
          (eq, ":object", "$g_show_no_more_respawns_remained"),
          (call_script, "script_setup_mod_keys"),
        # (else_try), #toggling camera mode means reloading string descriptions
          # (eq, ":object", "$g_dplmc_cam_activated"),
          # (store_trigger_param_2, ":value"),
          # (store_add, "$g_dplmc_cam_default", ":value", 1),
        (else_try),
          (eq, ":object", "$g_close_equipment_selection"),
          # provide actual exit conditions
          (assign, "$g_presentation_next_presentation", -1),
        (else_try),
          (gt, ":object", -1),
            #reset to black
          (overlay_set_alpha, "$g_presentation_obj_1", 0xff),
          (overlay_set_alpha, "$g_presentation_obj_2", 0xff),
          (overlay_set_alpha, "$g_presentation_obj_3", 0xff),
          (overlay_set_alpha, "$g_presentation_obj_4", 0xff),
          (overlay_set_alpha, "$g_presentation_obj_5", 0xff),
          (overlay_set_alpha, "$g_presentation_obj_6", 0xff),
          # (overlay_set_alpha, "$g_presentation_obj_11",0xff),
          # (overlay_set_alpha, "$g_presentation_obj_12",0xff),
          # (overlay_set_alpha, "$g_presentation_obj_13",0xff),
          # (overlay_set_alpha, "$g_presentation_obj_14",0xff),
          (assign, "$temp", ":object"),
          (overlay_set_alpha, "$temp", 0x80),
        (try_end),
        (try_begin),#done/reset
          (this_or_next|eq, ":object", "$g_show_no_more_respawns_remained"),
          # (this_or_next|eq, ":object", "$g_close_equipment_selection"),
          (eq, ":object", "$g_close_equipment_selection"),
          # (eq, ":object", "$g_dplmc_cam_activated"),
          (assign, "$temp", 0),
          (presentation_set_duration, 0),
          # (assign, "$g_presentation_next_presentation", "prsnt_mod_option"),
          # (start_presentation, "prsnt_mod_option"),
        (try_end),
    ]),
  ]),

("particle_preview", prsntf_manual_end_only, 0,[

      (ti_on_presentation_load,
      [
      (set_fixed_point_multiplier, 1000),
      (presentation_set_duration, 999999),

      # Background mesh
      (create_mesh_overlay, "$pp_background", "mesh_ui_quick_battle_a", tf_center_justify),
      (position_set_x, pos1, 750),
      (position_set_y, pos1, 750),
      (overlay_set_size, "$pp_background", pos1),

      # Title text
      (str_store_string, s1, "@Particle Preview"),
      (create_text_overlay, "$pp_title", s1, tf_with_outline|tf_center_justify),
      (overlay_set_color, "$pp_title", 0xC5B58D),
      (position_set_x, pos1, 1700),
      (position_set_y, pos1, 1700),
      (overlay_set_size, "$pp_title", pos1),
      (position_set_x, pos1, 140),
      (position_set_y, pos1, 500),
      (overlay_set_position, "$pp_title", pos1),

      # ID number box
      (assign, reg50, 155), # this is ID of the last particle in ID_particle_systems.py of your module (60 for Native)
      (store_add, ":limit", reg50, 1),
      (assign, "$pp_id_val", 0), # default value
      (create_number_box_overlay, "$pp_id", 0, ":limit", tf_center_justify),
      (position_set_x, pos1, 160),
      (position_set_y, pos1, 450),
      (overlay_set_position, "$pp_id", pos1),
      (str_store_string, s5, "@ID (0-{reg50}):"), # it will be automatically displayed as in-game upper bound
      (create_text_overlay, "$pp_id_text", s5, tf_right_align),
      (position_set_x, pos1, 155),
      (position_set_y, pos1, 450),
      (overlay_set_position, "$pp_id_text", pos1),

      # Strength number box
      (create_number_box_overlay, "$pp_str", 1, 1000000000, tf_center_justify),
      (position_set_x, pos1, 160),
      (position_set_y, pos1, 400),
      (overlay_set_position, "$pp_str", pos1),
      (overlay_set_val, "$pp_str", 100), # default value
      (assign, "$pp_str_val", 100),
      (str_store_string, s6, "@Strength (%):"),
      (create_text_overlay, "$pp_str_text", s6, tf_right_align),
      (position_set_x, pos1, 155),
      (position_set_y, pos1, 400),
      (overlay_set_position, "$pp_str_text", pos1),

      # Instances number box
      (create_number_box_overlay, "$pp_num", 1, 1000000000, tf_center_justify),
      (position_set_x, pos1, 160),
      (position_set_y, pos1, 350),
      (overlay_set_position, "$pp_num", pos1),
      (overlay_set_val, "$pp_num", 1), # default value
      (assign, "$pp_num_val", 1),
      (str_store_string, s7, "@Instances:"),
      (create_text_overlay, "$pp_num_text", s7, tf_right_align),
      (position_set_x, pos1, 155),
      (position_set_y, pos1, 350),
      (overlay_set_position, "$pp_num_text", pos1),

      # Plate distance slider
      (create_slider_overlay, "$pp_dist", 50, 4160, tf_center_justify), # these are game-tested min and max distance limits. Particle won't be visible beyond them
      (position_set_x, pos1, 157),
      (position_set_y, pos1, 300),
      (overlay_set_position, "$pp_dist", pos1),
      (position_set_x, pos1, 800),
      (position_set_y, pos1, 800),
      (overlay_set_size, "$pp_dist", pos1),
      (overlay_set_val, "$pp_dist", 170), # default value
      (assign, "$pp_dist_val", 170),
      (str_store_string, s8, "@Plate Distance"),
      (create_text_overlay, "$pp_dist_text", s8, tf_center_justify),
      (position_set_x, pos1, 135),
      (position_set_y, pos1, 275),
      (overlay_set_position, "$pp_dist_text", pos1),
      (position_set_x, pos1, 985),
      (position_set_y, pos1, 985),
      (overlay_set_size, "$pp_dist_text", pos1),

      # Description text
      (str_store_string, s2, "@Particle of your choice will be^emitted from the center of^wooden plate. Use ID .py file^to get 'psys' reference of^the number you see here."), # no full file name here cuz in strings game treats _ symbol as space sadly
      (create_text_overlay, "$pp_description", s2, tf_center_justify),
      (position_set_x, pos1, 130),
      (position_set_y, pos1, 170),
      (overlay_set_position, "$pp_description", pos1),
      (position_set_x, pos1, 900),
      (position_set_y, pos1, 900),
      (overlay_set_size, "$pp_description", pos1),

      # Emit button
      (str_store_string, s3, "@Emit Particle"),
      (create_in_game_button_overlay, "$pp_emit", s3, tf_center_justify),
      (position_set_x, pos1, 131),
      (position_set_y, pos1, 111),
      (overlay_set_position, "$pp_emit", pos1),

      # Exit button
      (str_store_string, s4, "@Close Window"),
      (create_game_button_overlay, "$pp_close", s4, tf_center_justify),
      (position_set_x, pos1, 130),
      (position_set_y, pos1, 35),
      (overlay_set_position, "$pp_close", pos1),

      # Plate creation
      (mission_cam_get_position, pos2),
      (set_spawn_position, pos2),
      (spawn_scene_prop, "spr_plate_a"),
      (assign, "$pp_plate", reg0),
      ]),

      (ti_on_presentation_run,
      [
      (mission_cam_get_position, pos2), # always screen-centrified
      (position_move_x, pos2, -50),
      (position_move_y, pos2, "$pp_dist_val"), # making it slider-dependant
      (position_rotate_x, pos2, 30),
      (position_rotate_y, pos2, 7), # slightly tilting for better view on particle
      (prop_instance_set_position, "$pp_plate", pos2),
      (try_begin),
        (this_or_next|game_key_clicked, gk_quests_window), # all keys that can close presentation should also remove the plate not to make clutter
        (this_or_next|game_key_clicked, gk_game_log_window),
        (this_or_next|game_key_clicked, gk_party_window),
        (this_or_next|game_key_clicked, gk_inventory_window),
        (this_or_next|game_key_clicked, gk_character_window),
        (key_clicked, key_escape),
        (scene_prop_set_visibility, "$pp_plate", 0),
        (prop_instance_get_position, pos3, "$pp_plate"),
        (position_move_z, pos3, -3000, 1),
        (prop_instance_set_position, "$pp_plate", pos3),
        (assign, "$pp_plate", -1),
      (try_end),
      ]),

      (ti_on_presentation_event_state_change,
      [
        (store_trigger_param_1, ":object"),
        (store_trigger_param_2, ":value"),
        (try_begin),
          (eq, ":object", "$pp_id"),
          (assign, "$pp_id_val", ":value"),
        (else_try),
          (eq, ":object", "$pp_str"),
          (assign, "$pp_str_val", ":value"),
        (else_try),
          (eq, ":object", "$pp_num"),
          (assign, "$pp_num_val", ":value"),
        (else_try),
          (eq, ":object", "$pp_dist"),
          (assign, "$pp_dist_val", ":value"),
        (else_try),
          (eq, ":object", "$pp_emit"),
          (prop_instance_get_position, pos2, "$pp_plate"),
          (try_for_range, ":iteration", 0, "$pp_num_val"),
            (lt, ":iteration", "$pp_num_val"), # no need to check for lt as this is already how loops work but this line prevents compiler warning
            (particle_system_burst, "$pp_id_val", pos2, "$pp_str_val"),
          (try_end),
        (else_try),
          (eq, ":object", "$pp_close"),
          (presentation_set_duration, 0),
          (scene_prop_set_visibility, "$pp_plate", 0), # removing the plate upon closing
          (prop_instance_get_position, pos3, "$pp_plate"),
          (position_move_z, pos3, -3000, 1),
          (prop_instance_set_position, "$pp_plate", pos3),
          (assign, "$pp_plate", -1),
        (try_end),
      ]),
  ]),
